    20→// RuntimeValue — 인터프리터가 다루는 값
    21→// ============================================================
    22→
    23→export type RuntimeValue =
    24→  | { tag: "number"; val: number }
    25→  | { tag: "bool"; val: boolean }
    26→  | { tag: "string"; val: string }
    27→  | { tag: "tensor"; data: number[]; shape: number[] }
    28→  | { tag: "autograd"; val: AutoValue }
    29→  | { tag: "array"; val: RuntimeValue[] }
    30→  | { tag: "fn"; params: string[]; body: Stmt[]; closure: Env }
    31→  | { tag: "builtin"; fn: (...args: RuntimeValue[]) => RuntimeValue }
    32→  | { tag: "null" }
    33→  | { tag: "native"; val: unknown };  // FS/HTTP/DB/Collections 등 네이티브 객체
    34→
    35→// ============================================================
    36→// Environment (스코프 체인)
    37→// ============================================================
    38→
    39→export class Env {
    40→  private vars: Map<string, RuntimeValue> = new Map();
    41→  constructor(public parent: Env | null = null) {}
    42→
    43→  get(name: string): RuntimeValue {
    44→    if (this.vars.has(name)) return this.vars.get(name)!;
    45→    if (this.parent) return this.parent.get(name);
    46→    throw new RuntimeError(`정의되지 않은 변수: ${name}`);
    47→  }
    48→
    49→  set(name: string, val: RuntimeValue): void {
    50→    this.vars.set(name, val);
    51→  }
    52→
    53→  assign(name: string, val: RuntimeValue): void {
    54→    if (this.vars.has(name)) { this.vars.set(name, val); return; }
    55→    if (this.parent) { this.parent.assign(name, val); return; }
    56→    throw new RuntimeError(`정의되지 않은 변수: ${name}`);
    57→  }
    58→}
