// FreeLang v8 ML — REPL (Read-Eval-Print Loop) Phase 11

import * as readline from "readline";
import { Interpreter, RuntimeValue } from "../runtime/interpreter";
import { Lexer } from "../lexer/lexer";
import { Parser } from "../parser/parser";

const VERSION = "8.0.0";

const BANNER = `
╔══════════════════════════════════════════════╗
║   FreeLang v${VERSION} ML — Interactive REPL      ║
║   .help 로 도움말 | .exit 로 종료             ║
╚══════════════════════════════════════════════╝
`;

const HELP_TEXT = `
FreeLang v8 ML REPL 명령어:
  .exit  / .quit   — 종료
  .clear           — 환경 초기화 (변수/함수 모두 삭제)
  .help            — 이 도움말 출력
  .history         — 최근 10개 명령 출력
  .vars            — 현재 정의된 변수/함수 목록

입력 방법:
  - 한 줄 코드: 즉시 실행
  - { 로 시작하는 블록: } 로 닫힐 때까지 버퍼링 (멀티라인)
  - 결과는 "→ <값>" 형식으로 출력

예시:
  fl8> let x = 42
  fl8> x + 1
  → 43
  fl8> fn add(a, b) { a + b }
  fl8> add(10, 20)
  → 30
`;

// ============================================================
// 유틸리티 함수 (export — 테스트 가능)
// ============================================================

/**
 * RuntimeValue를 사람이 읽기 좋은 문자열로 포맷.
 * null 태그면 null 반환 (출력 생략).
 */
export function formatResult(rv: RuntimeValue): string | null {
  if (rv.tag === "null") return null;
  if (rv.tag === "number") {
    // 정수면 소수점 없이
    return Number.isInteger(rv.val) ? String(rv.val) : String(rv.val);
  }
  if (rv.tag === "bool") return rv.val ? "true" : "false";
  if (rv.tag === "string") return `"${rv.val}"`;
  if (rv.tag === "array") {
    const items = rv.val.map(v => formatResult(v) ?? "null");
    return `[${items.join(", ")}]`;
  }
  if (rv.tag === "tensor") {
    return `Tensor(shape=[${rv.shape.join(",")}], data=[${rv.data.slice(0, 6).map(n => n.toFixed(4)).join(", ")}${rv.data.length > 6 ? ", ..." : ""}])`;
  }
  if (rv.tag === "fn") {
    return `<fn(${rv.params.join(", ")})>`;
  }
  if (rv.tag === "builtin") {
    return `<builtin>`;
  }
  if (rv.tag === "autograd") {
    return `AutoGrad(${rv.val?.data ?? "?"})`;
  }
  if (rv.tag === "native") {
    return `<native object>`;
  }
  return JSON.stringify(rv);
}

/**
 * 현재 버퍼가 멀티라인 계속 입력 상태인지 판단.
 * { 의 개수가 } 보다 많으면 계속 입력 필요.
 */
export function isMultilineContinue(buffer: string[]): boolean {
  const joined = buffer.join("\n");
  let depth = 0;
  let inString = false;
  let strChar = "";
  for (let i = 0; i < joined.length; i++) {
    const ch = joined[i];
    if (inString) {
      if (ch === "\\" && i + 1 < joined.length) { i++; continue; }
      if (ch === strChar) inString = false;
      continue;
    }
    if (ch === '"' || ch === "'") { inString = true; strChar = ch; continue; }
    if (ch === "{") depth++;
    else if (ch === "}") depth--;
  }
  return depth > 0;
}

// ============================================================
// REPL 클래스
// ============================================================

export class FL8Repl {
  private interp: Interpreter;
  private history: string[] = [];
  private multilineBuffer: string[] = [];

  constructor() {
    this.interp = new Interpreter();
  }

  /** REPL 시작 */
  start(): void {
    console.log(BANNER);

    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
      terminal: true,
    });

    const prompt = () => {
      const isMulti = this.multilineBuffer.length > 0;
      rl.setPrompt(isMulti ? "...  " : "fl8> ");
      rl.prompt();
    };

    prompt();

    rl.on("line", (line: string) => {
      this.handleLine(line, rl, prompt);
    });

    rl.on("close", () => {
      console.log("\n안녕히 가세요!");
      process.exit(0);
    });
  }

  /** 한 줄 입력 처리 (readline에서 호출) */
  private handleLine(
    line: string,
    rl: readline.Interface,
    prompt: () => void
  ): void {
    const trimmed = line.trim();

    // 멀티라인 버퍼가 비어있을 때만 특수 명령어 처리
    if (this.multilineBuffer.length === 0) {
      if (trimmed === ".exit" || trimmed === ".quit") {
        rl.close();
        return;
      }
      if (trimmed === ".help") {
        console.log(HELP_TEXT);
        prompt();
        return;
      }
      if (trimmed === ".clear") {
        this.interp = new Interpreter();
        this.multilineBuffer = [];
        console.log("환경이 초기화되었습니다.");
        prompt();
        return;
      }
      if (trimmed === ".history") {
        const recent = this.history.slice(-10);
        if (recent.length === 0) {
          console.log("(기록 없음)");
        } else {
          recent.forEach((h, i) => console.log(`  ${i + 1}: ${h}`));
        }
        prompt();
        return;
      }
      if (trimmed === ".vars") {
        const names = this.interp.getGlobalNames();
        // 내장 함수 제외하고 사용자 정의만 표시하거나 전체 표시
        if (names.length === 0) {
          console.log("(정의된 변수/함수 없음)");
        } else {
          console.log("정의된 이름들:");
          for (const name of names) {
            console.log(`  ${name}`);
          }
        }
        prompt();
        return;
      }
      // 빈 줄 무시
      if (trimmed === "") {
        prompt();
        return;
      }
    }

    // 멀티라인 버퍼에 추가
    this.multilineBuffer.push(line);

    // 멀티라인 계속 여부 확인
    if (isMultilineContinue(this.multilineBuffer)) {
      prompt();
      return;
    }

    // 실행
    const src = this.multilineBuffer.join("\n");
    this.multilineBuffer = [];

    // 히스토리 저장 (빈 줄 제외)
    const histSrc = src.trim();
    if (histSrc) {
      this.history.push(histSrc);
      if (this.history.length > 100) this.history.shift();
    }

    this.execute(src);
    prompt();
  }

  /** 소스 코드 실행 및 결과 출력 */
  private execute(src: string): void {
    try {
      const { tokens, errors: lexErrors } = new Lexer(src).tokenize();
      if (lexErrors.length > 0) {
        for (const e of lexErrors) {
          console.error(`[Lex 오류] ${e.line}:${e.col}: ${e.message}`);
        }
        return;
      }

      const { program, errors: parseErrors } = new Parser(tokens).parse();
      if (parseErrors.length > 0) {
        for (const e of parseErrors) {
          console.error(`[파서 오류] ${e.line}:${e.col}: ${e.message}`);
        }
        return;
      }

      const rv = this.interp.runInGlobal(program);
      const formatted = formatResult(rv);
      if (formatted !== null) {
        console.log(`→ ${formatted}`);
      }
    } catch (e: any) {
      // 오류가 있어도 인터프리터 상태 유지 (재시작 안 함)
      console.error(`[런타임 오류] ${e.message}`);
    }
  }
}

