import { Interpreter, RuntimeValue } from "../src/runtime/interpreter";
import { Lexer } from "../src/lexer/lexer";
import { Parser } from "../src/parser/parser";
import { formatResult, isMultilineContinue } from "../src/repl/repl";

// ============================================================
// 테스트 프레임워크
// ============================================================

let passed = 0;
let failed = 0;
const failedNames: string[] = [];

function test(name: string, fn: () => void): void {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
    failedNames.push(name);
  }
}

function assert(cond: boolean, msg: string): void {
  if (!cond) throw new Error(msg);
}

function assertEqual<T>(a: T, b: T, msg?: string): void {
  const ja = JSON.stringify(a);
  const jb = JSON.stringify(b);
  if (ja !== jb) throw new Error(msg ?? `expected ${jb}, got ${ja}`);
}

// ============================================================
// REPL 세션 시뮬레이터
// Interpreter 인스턴스를 유지하며 여러 번 runInGlobal() 호출
// ============================================================

function makeSession() {
  const interp = new Interpreter();

  function exec(src: string): RuntimeValue {
    const { tokens, errors: lexErr } = new Lexer(src).tokenize();
    if (lexErr.length > 0) throw new Error(`Lex: ${lexErr[0].message}`);
    const { program, errors: parseErr } = new Parser(tokens).parse();
    if (parseErr.length > 0) throw new Error(`Parse: ${parseErr[0].message}`);
    return interp.runInGlobal(program);
  }

  function getNames(): string[] {
    return interp.getGlobalNames();
  }

  return { exec, getNames, interp };
}

