  const { exec } = makeSession();
  exec("let x = 10");
  const rv = exec("x");
  assertEqual(rv, { tag: "number", val: 10 });
});

test("함수 선언 후 다음 실행에서 호출 가능", () => {
  const { exec } = makeSession();
  exec("fn double(n) { n * 2 }");
  const rv = exec("double(21)");
  assertEqual(rv, { tag: "number", val: 42 });
});

test("변수 재할당 반영됨", () => {
  const { exec } = makeSession();
  exec("let count = 0");
  exec("count = count + 1");
  exec("count = count + 1");
  const rv = exec("count");
  assertEqual(rv, { tag: "number", val: 2 });
});

test("여러 변수 독립 유지", () => {
  const { exec } = makeSession();
  exec("let a = 100");
  exec("let b = 200");
  const ra = exec("a");
  const rb = exec("b");
  assertEqual(ra, { tag: "number", val: 100 });
  assertEqual(rb, { tag: "number", val: 200 });
});

