console.log("\n[2] 누적 실행 테스트");

test("순차 실행: a + b + c", () => {
  const { exec } = makeSession();
  exec("let a = 1");
  exec("let b = 2");
  exec("let c = 3");
  const rv = exec("a + b + c");
